// The mind map drawn by mind-elixir.
//
// The one of the three that is a mind map *editor* rather than a picture: a
// node can be dragged onto another branch, folded, edited, and the whole map
// panned and zoomed. Nothing it does is written back to the org files - this
// view is for reading a plan and rearranging it to think, and a drag that
// silently refiled a heading is not what somebody moving nodes around expects.
//
// It keeps its own DOM, so React's only jobs are to hand it a tree when the
// tree changes and to take it down again. Re-creating the instance on every
// change is deliberate: mind-elixir has a `refresh`, but it keeps the old
// theme's css variables, and a map that half-changed colour when the app went
// dark is worse than one that redraws.

import * as React from 'react';
import Box from '@mui/joy/Box';

import MindElixirCtor from 'mind-elixir';
import 'mind-elixir/style';

import {
    DensityValues, MindDirection, MindLook, MindNode, NodeStyle, toElixir,
} from '../mindmap';

export interface MindElixirHandle {
    // The drawn map as an svg document, for saving.
    svg: () => Promise<string>;
    fit: () => void;
    zoom: (by: number) => void;
}

interface Props {
    root: MindNode;
    look: MindLook;
    colorFor: (n: MindNode) => string;
    textOn: (bg: string) => string;
    show: { status: boolean; priority: boolean; tags: boolean };
    openTo: number;
    editable: boolean;
    // Straight branches or curved ones - the one thing about the drawing that
    // is a matter of taste rather than of theme.
    line: 'curve' | 'straight';
    nodeStyle: NodeStyle;
    density: DensityValues;
    direction: MindDirection;
    // Line the branches up on the root or on each other.
    alignment: 'root' | 'nodes';
    onPick?: (id: string) => void;
}

// Which way mind-elixir spreads. Its own constants are 0 left, 1 right,
// 2 both sides, 3 downwards.
const DIRECTION_CODE: Record<MindDirection, number> = {
    left: 0, right: 1, side: 2, down: 3,
};

// A branch drawn as two straight runs rather than a curve. mind-elixir asks
// for the path itself, which is the only way to change the shape of a line -
// the `mainLinkStyle` option older versions had is gone.
function straightMain(p: any): string {
    const { pT, pL, pW, pH, cT, cL, cW, cH, direction } = p;
    const from = { x: direction === 'lhs' ? pL : pL + pW, y: pT + pH / 2 };
    const to = { x: direction === 'lhs' ? cL + cW : cL, y: cT + cH / 2 };
    const mid = (from.x + to.x) / 2;
    return `M ${from.x} ${from.y} L ${mid} ${from.y} L ${mid} ${to.y} L ${to.x} ${to.y}`;
}

function straightSub(p: any): string {
    const { pT, pL, pW, pH, cT, cL, cW, cH, direction } = p;
    const from = { x: direction === 'lhs' ? pL : pL + pW, y: pT + pH };
    const to = { x: direction === 'lhs' ? cL + cW : cL, y: cT + cH };
    const mid = direction === 'lhs' ? from.x - 20 : from.x + 20;
    return `M ${from.x} ${from.y} L ${mid} ${from.y} L ${mid} ${to.y} L ${to.x} ${to.y}`;
}

const MindElixir = React.forwardRef<MindElixirHandle, Props>(function MindElixir(props, ref) {
    const hostRef = React.useRef<HTMLDivElement>(null);
    const meRef = React.useRef<any>(null);
    const pickRef = React.useRef(props.onPick);
    pickRef.current = props.onPick;

    const {
        root, look, colorFor, textOn, openTo, editable, line,
        nodeStyle, density, direction, alignment,
    } = props;
    const { status, priority, tags } = props.show;

    React.useEffect(() => {
        const host = hostRef.current;
        if (!host) return;
        host.innerHTML = '';

        const data = toElixir(root, {
            status, priority, tags,
            colorFor, textOn, openTo,
            style: nodeStyle, pageInk: look.text,
        });

        // mind-elixir themes are a name, a palette and a bag of css variables.
        // The variables are what the lines, the panel and the selection are
        // drawn from, so this is where following the app's light and dark
        // actually happens.
        const theme = {
            name: look.dark ? 'orgs-dark' : 'orgs-light',
            palette: look.palette,
            cssVar: {
                '--main-color': look.text,
                '--main-bgcolor': look.ground,
                '--color': look.text,
                '--bgcolor': look.panel,
                '--panel-color': look.text,
                '--panel-bgcolor': look.panel,
                '--panel-border-color': look.border,
                '--selected': look.accent,
                '--root-color': textOn(look.rootBg),
                '--root-bgcolor': look.rootBg,
                '--root-border-color': look.rootBg,
                '--line-color': look.line,
                '--line-width': '2',
                '--node-gap-x': `${density.gapX}px`,
                '--node-gap-y': `${density.gapY}px`,
                '--main-gap-x': `${density.mainGapX}px`,
                '--main-gap-y': `${density.mainGapY}px`,
                '--topic-padding': density.padding,
                '--main-radius': density.radius,
                '--root-radius': density.radius,
                '--accent-color': look.accent,
            },
            ...(line === 'straight'
                ? { generateMainBranch: straightMain, generateSubBranch: straightSub }
                : {}),
        } as any;

        const me = new (MindElixirCtor as any)({
            el: host,
            direction: DIRECTION_CODE[direction],
            alignment,
            draggable: editable,
            editable,
            contextMenu: editable,
            toolBar: true,
            nodeMenu: editable,
            keypress: editable,
            theme,
        });
        me.init(data);
        meRef.current = me;

        // A node's id is the heading's hash, so telling the page which node was
        // chosen is enough for it to find the heading.
        const bus = me.bus;
        if (bus && typeof bus.addListener === 'function') {
            bus.addListener('selectNode', (n: any) => {
                if (pickRef.current && n && n.id) pickRef.current(n.id);
            });
        }

        return () => {
            meRef.current = null;
            host.innerHTML = '';
        };
    }, [root, look, colorFor, textOn, status, priority, tags, openTo, editable, line,
        nodeStyle, density, direction, alignment]);

    React.useImperativeHandle(ref, () => ({
        svg: async () => {
            const me = meRef.current;
            if (!me) return '';
            // exportSvg hands back a Blob; the caller wants the text of it.
            if (typeof me.exportSvg === 'function') {
                const blob = await me.exportSvg();
                if (blob && typeof blob.text === 'function') return await blob.text();
            }
            return '';
        },
        fit: () => { const me = meRef.current; if (me && me.toCenter) me.toCenter(); },
        zoom: (by: number) => {
            const me = meRef.current;
            if (!me || typeof me.scale !== 'function') return;
            const now = typeof me.scaleVal === 'number' ? me.scaleVal : 1;
            me.scale(Math.max(0.2, Math.min(3, now + by)));
        },
    }), []);

    return (
        <Box
            ref={hostRef}
            sx={{
                width: '100%', height: '100%', minHeight: 0,
                // mind-elixir paints its own ground from --main-bgcolor; this
                // is here so the corner radius has something to round.
                borderRadius: 'sm', overflow: 'hidden',
            }}
        />
    );
});

export default MindElixir;
